using System;using System.IO;using System.Linq;using System.Collections.Generic;using TMPro;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.TextCore.LowLevel;
namespace KominkaHillside.Editor {public static partial class KH_WashSelectionEditor {
 [MenuItem(Menu+"43 - Prepare Care Font")]
 public static void PrepareFont(){Guard();var chars=new string((string.Concat(ReadWords().languages.SelectMany(l=>l.words))+PhotoExtras+string.Concat(ListingSubtitles)).Where(c=>!char.IsControl(c)).Distinct().OrderBy(c=>c).ToArray());var p=Data+"CareFont.asset";var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(p);var src=AssetDatabase.LoadAssetAtPath<Font>("Assets/KominkaHillside/Font/Editor/WashPremium/NotoSerifCJKjp-Regular.otf");if(src==null)throw new Exception("CJK source missing");if(font==null){font=TMP_FontAsset.CreateFontAsset(src,36,4,GlyphRenderMode.SDFAA,2048,2048,AtlasPopulationMode.Dynamic,false);font.name="VAnimal Care";AssetDatabase.CreateAsset(font,p);foreach(var tx in font.atlasTextures)AssetDatabase.AddObjectToAsset(tx,font);AssetDatabase.AddObjectToAsset(font.material,font);}else{var so=new SerializedObject(font);so.FindProperty("m_SourceFontFile_EditorRef").objectReferenceValue=src;so.ApplyModifiedPropertiesWithoutUndo();font.atlasPopulationMode=AtlasPopulationMode.Dynamic;}
 string missing=new string(chars.Where(c=>!font.HasCharacter(c)).ToArray());if(missing.Length>0)font.TryAddCharacters(missing,out _);missing=new string(chars.Where(c=>!font.HasCharacter(c)).ToArray());if(missing.Length>0){string lp=Data+"CareLatin.asset";var latin=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(lp);if(latin==null){var ls=AssetDatabase.LoadAssetAtPath<Font>("Assets/TextMesh Pro/Fonts/LiberationSans.ttf");latin=TMP_FontAsset.CreateFontAsset(ls,36,4,GlyphRenderMode.SDFAA,512,512,AtlasPopulationMode.Dynamic,false);latin.name="VAnimal Care Latin";AssetDatabase.CreateAsset(latin,lp);foreach(var tx in latin.atlasTextures)AssetDatabase.AddObjectToAsset(tx,latin);AssetDatabase.AddObjectToAsset(latin.material,latin);latin.TryAddCharacters(missing,out _);latin.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(latin);}font.fallbackFontAssetTable=new List<TMP_FontAsset>{latin};}
 font.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(font);AssetDatabase.SaveAssets();missing=new string(chars.Where(c=>!font.HasCharacter(c,true)).ToArray());if(missing.Length>0)throw new Exception("Unbaked characters: "+missing);int labels=0;foreach(var b in UnityEngine.Object.FindObjectsOfType<KH_WashSelectionBoard>(true)){foreach(var t in b.GetComponentsInChildren<TMP_Text>(true)){t.font=font;EditorUtility.SetDirty(t);labels++;}}EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveOpenScenes();Log("font","unique="+chars.Length+" glyphs="+font.glyphTable.Count+" missing="+missing.Length+" labels="+labels+" 2048 square Alpha8; source runtime reference removed");}
}}
